HOMOGLYPH_MAP = str.maketrans({
    "а": "a", "е": "e", "о": "o", "р": "p", "с": "c", "у": "y", "х": "x", "к": "k",
    "А": "A", "В": "B", "Е": "E", "К": "K", "М": "M", "Н": "H", "О": "O", "Р": "P", "С": "C", "Т": "T", "Х": "X",
})


def apply_homoglyphs(text: str, words: list[str]) -> str:
    """Replace Cyrillic letters with Latin lookalikes inside target keywords."""
    out = text
    for w in words:
        out = out.replace(w, w.translate(HOMOGLYPH_MAP))
    return out


